package dev.pocket.agent;
import android.app.*;
import android.content.*;
import android.os.*;
import android.speech.tts.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

/** Lock-screen call-style page: answering reveals the message and starts Android TTS. */
public class BotAlertActivity extends Activity {
    private TextToSpeech speech;private JSONObject alert;private TextView message,status,answerLabel,declineLabel;private AgentIcon answerButton;private WorkingAvatarView avatar;private LinearLayout timerSlot;private boolean answered;private final Handler main=new Handler(Looper.getMainLooper());private final Runnable voiceTimeout=() -> status.setText("Voice is taking a moment. Your message is below.");
    private int dp(int v){return AgentStyle.dp(this,v);}
    private TextView label(String value,int size,int color){TextView view=AgentStyle.text(this,value,size);view.setGravity(Gravity.CENTER);view.setTextColor(color);return view;}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);if(Build.VERSION.SDK_INT>=27){setShowWhenLocked(true);setTurnScreenOn(true);}else getWindow().addFlags(WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON);
        getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);androidx.core.view.WindowCompat.setDecorFitsSystemWindows(getWindow(),false);getWindow().setStatusBarColor(android.graphics.Color.TRANSPARENT);getWindow().setNavigationBarColor(android.graphics.Color.TRANSPARENT);if(Build.VERSION.SDK_INT>=29)getWindow().setNavigationBarContrastEnforced(false);new androidx.core.view.WindowInsetsControllerCompat(getWindow(),getWindow().getDecorView()).setAppearanceLightStatusBars(false);
        try{alert=BotNotifications.alert(this,getIntent().getStringExtra("alertId"));if(!alert.has("id")){finish();return;}}catch(Exception e){finish();return;}
        JSONObject identity=BotNotifications.identity(this,alert);int tint;try{tint=android.graphics.Color.parseColor(identity.optString("accent","#007AFF"));}catch(Exception e){tint=0xff007aff;}
        FrameLayout root=new FrameLayout(this);root.setBackground(new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0xff17171c,0xff08080a}));
        View glow=new View(this);android.graphics.drawable.GradientDrawable halo=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TOP_BOTTOM,new int[]{(tint&0xffffff)|0x35000000,0x0017171c});halo.setGradientType(android.graphics.drawable.GradientDrawable.RADIAL_GRADIENT);halo.setGradientRadius(dp(230));glow.setBackground(halo);FrameLayout.LayoutParams glowSize=new FrameLayout.LayoutParams(-1,dp(440),Gravity.TOP);root.addView(glow,glowSize);
        LinearLayout page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setGravity(Gravity.CENTER_HORIZONTAL);page.setPadding(dp(28),dp(56),dp(28),dp(30));page.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(dp(28),dp(24)+insets.getSystemWindowInsetTop(),dp(28),dp(24)+insets.getSystemWindowInsetBottom());return insets;});root.addView(page,new FrameLayout.LayoutParams(-1,-1));
        TextView brand=label("POCKOBOTS",12,0xffa1a1aa);brand.setLetterSpacing(.16f);page.addView(brand);View topSpace=new View(this);page.addView(topSpace,new LinearLayout.LayoutParams(1,0,0.25f));
        avatar=new WorkingAvatarView(this,identity,42);avatar.setWorking(true);LinearLayout.LayoutParams avatarSize=new LinearLayout.LayoutParams(dp(122),dp(122));avatarSize.bottomMargin=dp(26);page.setClipChildren(false);page.addView(avatar,avatarSize);
        TextView name=label(identity.optString("name",alert.optString("botName")),34,0xfffafafa);name.setTypeface(AgentStyle.font(this),android.graphics.Typeface.BOLD);page.addView(name,new LinearLayout.LayoutParams(-1,-2));status=label("Incoming bot call",15,0xffa1a1aa);status.setContentDescription("bot-alert-voice-status");status.setPadding(0,dp(12),0,dp(6));page.addView(status);
        timerSlot=new LinearLayout(this);timerSlot.setGravity(Gravity.CENTER);page.addView(timerSlot,new LinearLayout.LayoutParams(-1,dp(26)));
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(false);scroll.setClipToPadding(false);message=label("Answer to hear your bot's message",16,0xffd4d4d8);message.setPadding(dp(8),dp(24),dp(8),dp(24));scroll.addView(message);LinearLayout.LayoutParams scrollSize=new LinearLayout.LayoutParams(-1,0,1);scrollSize.topMargin=dp(16);page.addView(scroll,scrollSize);
        LinearLayout controls=new LinearLayout(this);controls.setGravity(Gravity.CENTER);controls.setPadding(0,dp(24),0,dp(8));
        LinearLayout decline=controlColumn();AgentIcon endCall=callButton("phone","Decline bot call",0xffff453a,()->{stopRinging("dismiss");finish();});endCall.setRotation(135);decline.addView(endCall,new LinearLayout.LayoutParams(dp(76),dp(76)));declineLabel=label("Decline",13,0xffe4e4e7);declineLabel.setPadding(0,dp(12),0,0);decline.addView(declineLabel);controls.addView(decline,new LinearLayout.LayoutParams(0,-2,1));
        LinearLayout answer=controlColumn();answerButton=callButton("phone","Answer bot call",0xff30b95a,()->{if(answered){startActivity(new Intent(this,BotsActivity.class).putExtra("botId",alert.optString("botId")));finish();}else answerCall();});answer.addView(answerButton,new LinearLayout.LayoutParams(dp(76),dp(76)));answerLabel=label("Answer",13,0xffe4e4e7);answerLabel.setPadding(0,dp(12),0,0);answer.addView(answerLabel);controls.addView(answer,new LinearLayout.LayoutParams(0,-2,1));page.addView(controls,new LinearLayout.LayoutParams(-1,-2));setContentView(root);root.requestApplyInsets();if(getIntent().getBooleanExtra("answer",false))answerCall();
    }
    private LinearLayout controlColumn(){LinearLayout column=new LinearLayout(this);column.setOrientation(LinearLayout.VERTICAL);column.setGravity(Gravity.CENTER);return column;}
    private AgentIcon callButton(String symbol,String description,int color,Runnable action){AgentIcon button=new AgentIcon(this,symbol,description,action);button.setIconTint(0xffffffff);button.setGlyphSize(30);button.setBackground(AgentStyle.surface(this,color,40,false));return button;}
    private void answerCall(){if(answered)return;answered=true;avatar.setWorking(false);answerButton.setSymbol("open");answerButton.setContentDescription("Open bot chat");answerButton.setBackground(AgentStyle.surface(this,0xff007aff,40,false));answerLabel.setText("Open chat");declineLabel.setText("End");stopRinging("answer");new ChatMarkdown(this).set(message,alert.optString("text"));message.setTextColor(0xfffafafa);message.setGravity(Gravity.START);ElapsedTimeView elapsed=new ElapsedTimeView(this,System.currentTimeMillis(),0,true);elapsed.setTextColor(0xffa1a1aa);timerSlot.addView(elapsed);speak();}
    private void stopRinging(String action){startService(new Intent(this,BotAlertService.class).setAction(action).putExtra("alertId",alert.optString("id")));}
    private void speak(){status.setText("Starting Android voice…");main.postDelayed(voiceTimeout,10000);speech=new TextToSpeech(this,result -> main.post(() -> {main.removeCallbacks(voiceTimeout);if(isFinishing()||speech==null)return;if(result!=TextToSpeech.SUCCESS){status.setText("Voice unavailable · read the message above");return;}
        Voice offline=null;Set<Voice> voices=speech.getVoices();if(voices!=null)for(Voice voice:voices)if(!voice.isNetworkConnectionRequired()&&(voice.getFeatures()==null||!voice.getFeatures().contains(TextToSpeech.Engine.KEY_FEATURE_NOT_INSTALLED))&&voice.getLocale().getLanguage().equals(Locale.getDefault().getLanguage())){offline=voice;break;}
        if(offline==null){status.setText("No offline Android voice installed · message shown above");return;}if(speech.setVoice(offline)!=TextToSpeech.SUCCESS){status.setText("Voice unavailable - message shown above");return;}speech.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){runOnUiThread(() -> status.setText("Reading the bot's message"));}public void onDone(String id){runOnUiThread(() -> status.setText("Message read · tap Open chat to reply"));}public void onError(String id){runOnUiThread(() -> status.setText("Voice unavailable · message shown above"));}});
        if(speech.speak(message.getText().toString(),TextToSpeech.QUEUE_FLUSH,null,"bot-alert")==TextToSpeech.ERROR)status.setText("Voice unavailable - message shown above");}));}
    @Override protected void onDestroy(){main.removeCallbacksAndMessages(null);if(speech!=null){speech.stop();speech.shutdown();}super.onDestroy();}
}
